import{c as a,S as r,j as t,m as o}from"./chunks/framework.Ud3Za4F6.js";const p=JSON.parse('{"title":"Publications","description":"","frontmatter":{},"headers":[],"relativePath":"docs/publications/index.md","filePath":"docs/publications/index.md"}'),n={name:"docs/publications/index.md"};function i(l,e,s,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="publications" tabindex="-1">Publications <a class="header-anchor" href="#publications" aria-label="Permalink to “Publications”">​</a></h1><p>Publications about Source Academy, its languages, and the tools built with it, by members of the community. All entries are in one BibTeX file: <a href="/developers/source-academy.bib">source-academy.bib</a>.</p><h2 id="book" tabindex="-1">Book <a class="header-anchor" href="#book" aria-label="Permalink to “Book”">​</a></h2><ul><li>Harold Abelson and Gerald Jay Sussman with Julie Sussman; adapted to JavaScript by Martin Henz and Tobias Wrigstad with Julie Sussman. <em>Structure and Interpretation of Computer Programs, JavaScript Edition</em>. MIT Press, April 2022. ISBN 9780262543231. <a href="https://sourceacademy.org/sicpjs" target="_blank" rel="noreferrer">Read online</a>, <a href="https://sicp.sourceacademy.org/sicpjs.pdf" target="_blank" rel="noreferrer">PDF</a>.</li></ul><h2 id="papers" tabindex="-1">Papers <a class="header-anchor" href="#papers" aria-label="Permalink to “Papers”">​</a></h2><h3 id="_2026" tabindex="-1">2026 <a class="header-anchor" href="#_2026" aria-label="Permalink to “2026”">​</a></h3><ul><li>Qixiang Zhang, Feng Ding, Daoxin Li, Martin Henz. <em>More Pie for the Little Typer: Accessible, Extensible, and AI-Guided Proof Education</em>. SPLASH-E 2026, pp. 13–23. <a href="https://doi.org/10.1145/3841644.3842687" target="_blank" rel="noreferrer">DOI</a>.</li></ul><h3 id="_2023" tabindex="-1">2023 <a class="header-anchor" href="#_2023" aria-label="Permalink to “2023”">​</a></h3><ul><li>Kaian Cai, Martin Henz, Kok-Lim Low, Xing Yu Ng, Jing Ren Soh, Kyn-Han Tang, Kar Wi Toh. <em>Visualizing Environments of Modern Scripting Languages</em>. CSEDU 2023 (15th International Conference on Computer Supported Education), pp. 146–153. <a href="https://doi.org/10.5220/0011766700003470" target="_blank" rel="noreferrer">DOI</a>.</li><li>Boyd Anderson, Martin Henz, Kok-Lim Low. <em>Community-driven Course and Tool Development for CS1</em>. SIGCSE Technical Symposium 2023, Toronto. <a href="https://doi.org/10.1145/3545945.3569740" target="_blank" rel="noreferrer">DOI</a>.</li></ul><h3 id="_2021" tabindex="-1">2021 <a class="header-anchor" href="#_2021" aria-label="Permalink to “2021”">​</a></h3><p>All four at SPLASH-E 2021, the ACM SIGPLAN International Symposium on SPLASH-E, 20 October 2021.</p><ul><li>Boyd Anderson, Martin Henz, Kok-Lim Low, Daryl Tan. <em>Shrinking JavaScript for CS1</em>. pp. 87–96. <a href="https://doi.org/10.1145/3484272.3484970" target="_blank" rel="noreferrer">DOI</a>.</li><li>Boyd Anderson, Martin Henz, Hao-Wei Tee. <em>Ruggedizing CS1 Robotics: Tools and Approaches for Online Teaching</em>. pp. 82–86. <a href="https://doi.org/10.1145/3484272.3484969" target="_blank" rel="noreferrer">DOI</a>.</li><li>Martin Henz, Thomas Tan, Zachary Chua, Peter Jung, Yee-Jian Tan, Xinyi Zhang, Jingjing Zhao. <em>A Stepper for a Functional JavaScript Sublanguage</em>. pp. 71–81. <a href="https://doi.org/10.1145/3484272.3484968" target="_blank" rel="noreferrer">DOI</a>.</li><li>Martin Henz, Shang-Hui Koh, Samyukta Sounderraman. <em>Teachable Moments in Functional Audio Processing</em>. pp. 65–70. <a href="https://doi.org/10.1145/3484272.3484967" target="_blank" rel="noreferrer">DOI</a>.</li></ul><h2 id="keynote" tabindex="-1">Keynote <a class="header-anchor" href="#keynote" aria-label="Permalink to “Keynote”">​</a></h2><ul><li>Martin Henz, Tobias Wrigstad. <em>SICP JS: Ketchup on Caviar?</em> Keynote at the 2020 Scheme and Functional Programming Workshop, part of ICFP 2020, August 2020. <a href="https://arxiv.org/pdf/2101.06759.pdf" target="_blank" rel="noreferrer">Proceedings</a>, <a href="https://www.youtube.com/watch?v=8wsdHvnbcmY" target="_blank" rel="noreferrer">video</a>.</li></ul><h2 id="demos-and-talks" tabindex="-1">Demos and talks <a class="header-anchor" href="#demos-and-talks" aria-label="Permalink to “Demos and talks”">​</a></h2><ul><li>Martin Henz. <em>Source Academy: A Web-based Environment for Learning Programming with SICP</em>. Demonstration at the SIGCSE Technical Symposium 2023, Toronto. <a href="https://doi.org/10.1145/3545947.3573232" target="_blank" rel="noreferrer">DOI</a> (<a href="https://sigcse2023.sigcse.org/details/sigcse-ts-2023-demos/6/Source-Academy-A-Web-based-Environment-for-Learning-Programming-with-SICP" target="_blank" rel="noreferrer">conference page</a>).</li><li>Martin Henz. <em>&quot;Early X or Late X&quot; Questions for Discussing Curricular Practices in CS1 and CS2</em>. Lightning talk at the SIGCSE Technical Symposium 2023, Toronto. <a href="https://doi.org/10.1145/3545947.3573240" target="_blank" rel="noreferrer">DOI</a>.</li></ul><h2 id="how-to-cite" tabindex="-1">How to cite <a class="header-anchor" href="#how-to-cite" aria-label="Permalink to “How to cite”">​</a></h2><p>Cite the publication that matches what you used:</p><table tabindex="0"><thead><tr><th>You used</th><th>Cite</th></tr></thead><tbody><tr><td>the Source Academy platform</td><td><em>Source Academy: A Web-based Environment for Learning Programming with SICP</em> (SIGCSE 2023)</td></tr><tr><td>the Source languages (Source §1 to §4)</td><td><em>Shrinking JavaScript for CS1</em> (SPLASH-E 2021)</td></tr><tr><td>the stepper</td><td><em>A Stepper for a Functional JavaScript Sublanguage</em> (SPLASH-E 2021)</td></tr><tr><td>the textbook</td><td><em>Structure and Interpretation of Computer Programs, JavaScript Edition</em></td></tr><tr><td>Pie and proof education</td><td><em>More Pie for the Little Typer</em> (SPLASH-E 2026)</td></tr></tbody></table><p>Every entry, ready for BibTeX: <a href="/developers/source-academy.bib">source-academy.bib</a>.</p><p>Missing a publication? Open a pull request that adds it to <code>app/public/source-academy.bib</code> and to this page.</p>',21)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
